// SPDX-License-Identifier: Apache-2.0

import type { EngineInterface, Register } from 'claude-code'

type Finding = { severity: 'block' | 'warn'; file: string; line?: number; rule: string; why: string }
type Review = { findings: Finding[]; note?: string }

const PUSH = /(^|[;&|]\s*|\s)git\s+push\b/
const SKIP = /\bSKIP_REVIEW=1\b/
const MAX_DIFF_LINES = 3000
const SMALL_DIFF_LINES = 400
const MAX_DENIALS = 2

const EXCLUDE = [
  'package-lock.json', 'yarn.lock', 'pnpm-lock.yaml', '*.min.js', '*.map', '*.snap',
  'dist/**', 'build/**', 'coverage/**', '**/__generated__/**',
].map(p => `:(exclude,glob)${p}`)

const FALLBACK_GUIDELINES = `Flag only clear problems: leaked secrets, injection, missing auth on new routes,
unhandled promises, empty catch blocks, broken React hook rules (block); debug leftovers,
missing tests, \`any\` or @ts-ignore in TypeScript (warn).`

const SYSTEM = `You review a git diff before it is pushed. Apply only the guidelines given.
Report a finding only when the diff itself shows the problem and you are confident.
Use "block" only for the guideline's block rules. No style comments, no praise.
Reply with JSON only: {"findings":[{"severity":"block"|"warn","file":"...","line":123,"rule":"SEC-1","why":"one sentence"}]}.
An empty list is a good answer.`

async function git($: EngineInterface, args: string[]) {
  const r = await $.process.run(['git', ...args], { timeoutMs: 20000 })
  return r.exitCode === 0 ? r.stdout.trim() : undefined
}

// Options of `git push` that take a separate value argument.
const PUSH_VALUE_OPTS = new Set(['-o', '--push-option', '--repo', '--receive-pack', '--exec'])

type PushTarget = { remote?: string; src: string; dst?: string }

// Works out what a `git push` command pushes: `git push [opts] [remote] [src[:dst]]`.
// Without a refspec it pushes HEAD.
function parsePush(command: string): PushTarget {
  const m = PUSH.exec(command)
  if (!m) return { src: 'HEAD' }
  const rest = command.slice(m.index + m[0].length).split(/[;&|]/)[0] ?? ''
  const args: string[] = []
  const tokens = rest.trim().split(/\s+/).filter(Boolean)
  for (let i = 0; i < tokens.length; i++) {
    const t = tokens[i] ?? ''
    if (PUSH_VALUE_OPTS.has(t)) i++
    else if (!t.startsWith('-')) args.push(t.replace(/^['"]|['"]$/g, ''))
  }
  const [remote, refspec] = args
  if (!refspec) return { remote, src: 'HEAD' }
  const [src = '', dst] = refspec.replace(/^\+/, '').split(':')
  return { remote, src: src || 'HEAD', dst: dst?.replace(/^refs\/heads\//, '') || undefined }
}

async function review($: EngineInterface, target: PushTarget = { src: 'HEAD' }): Promise<Review> {
  const root = await git($, ['rev-parse', '--show-toplevel'])
  if (!root) return { findings: [], note: 'not a git repository, skipped' }
  const head = await git($, ['rev-parse', '--verify', `${target.src}^{commit}`])
  if (!head) return { findings: [], note: `could not resolve ${target.src}, skipped` }
  // Compare with the remote branch being pushed to if it exists, else the source's upstream, else origin/HEAD.
  const remote = target.remote ?? 'origin'
  const dstName = target.dst ?? (target.src === 'HEAD' ? undefined : target.src)
  const base =
    (dstName ? await git($, ['rev-parse', '--abbrev-ref', '--verify', `${remote}/${dstName}`]) : undefined) ??
    (await git($, ['rev-parse', '--abbrev-ref', `${target.src}@{upstream}`])) ??
    (await git($, ['rev-parse', '--abbrev-ref', 'origin/HEAD']))
  if (!base) return { findings: [], note: 'no upstream or origin/HEAD to compare with, skipped' }

  const cacheKey = `review:${root}:${base}:${head}`
  const cached = (await $.store.get(cacheKey)) as Review | undefined
  if (cached) return cached

  const diff = await git($, ['diff', '--unified=3', `${base}...${head}`, '--', '.', ...EXCLUDE])
  if (!diff) return { findings: [], note: `nothing new compared with ${base}` }
  const lines = diff.split('\n').length
  if (lines > MAX_DIFF_LINES)
    return { findings: [], note: `diff is ${lines} lines (over ${MAX_DIFF_LINES}), skipped; review it in smaller pushes` }

  const guidelines = await $.fs.read(`${root}/REVIEW_GUIDELINES.md`).catch(() => FALLBACK_GUIDELINES)
  const r = await $.model.complete({
    model: lines <= SMALL_DIFF_LINES ? 'haiku' : 'sonnet',
    system: SYSTEM,
    prompt: `<guidelines>\n${guidelines}\n</guidelines>\n\n<diff base="${base}">\n${diff}\n</diff>`,
    maxTokens: 2000,
    effort: 'low',
    timeoutMs: 90000,
  })
  if (!r.isAnswered) return { findings: [], note: `review failed (${r.reason}), not checked` }

  const json = r.text.slice(r.text.indexOf('{'), r.text.lastIndexOf('}') + 1)
  let result: Review
  try {
    result = { findings: (JSON.parse(json).findings ?? []) as Finding[] }
  } catch {
    return { findings: [], note: 'could not read the review reply, not checked' }
  }
  await $.store.set(cacheKey, result)
  return result
}

function format(r: Review) {
  return (
    r.note ??
    (r.findings.length === 0
      ? 'no findings'
      : r.findings
          .map(f => `[${f.severity}] ${f.rule} ${f.file}${f.line ? `:${f.line}` : ''}: ${f.why}`)
          .join('\n'))
  )
}

export const register: Register = on => {
  on('session.start', async ($, e, next) => {
    await $.command.register({ name: 'push-review', description: 'Review unpushed commits against REVIEW_GUIDELINES.md' })
    return next(e)
  })

  on('command.run', { command: 'push-review' }, async $ => {
    $.ui.status('pre-push review: running…')
    const r = await review($)
    $.ui.status(undefined)
    return { text: `Pre-push review: ${format(r)}` }
  })

  on('tool.call', { tool: 'Bash' }, async ($, e, next) => {
    if (!PUSH.test(e.command) || / --dry-run\b/.test(e.command)) return next(e)
    if (SKIP.test(e.command)) {
      $.ui.toast('pre-push review: skipped (SKIP_REVIEW=1)')
      return next(e)
    }

    $.ui.status('pre-push review: running…')
    const target = parsePush(String(e.command))
    const r = await review($, target).catch(err => ({ findings: [], note: `review error (${err}), not checked` }) as Review)
    $.ui.status(undefined)

    const branch = (await git($, ['rev-parse', '--abbrev-ref', target.src])) ?? '?'
    const denialsKey = `denials:${await $.session.cwd()}:${branch}`
    const blocking = r.findings.filter(f => f.severity === 'block')

    if (blocking.length > 0) {
      const denials = ((await $.store.get(denialsKey)) as number | undefined) ?? 0
      if (denials < MAX_DENIALS) {
        await $.store.set(denialsKey, denials + 1)
        return {
          deny:
            `Pre-push review found ${blocking.length} blocking issue(s). Fix them, commit, and push again. ` +
            `If a finding is wrong, tell the user and let them decide; they can push with SKIP_REVIEW=1.\n\n${format(r)}`,
        }
      }
      $.ui.toast(`pre-push review: pushing after ${denials} blocked attempts; ${blocking.length} issue(s) remain`)
    } else {
      $.ui.toast(`pre-push review: ${r.note ?? (r.findings.length ? `${r.findings.length} warning(s)` : 'no findings')}`)
    }
    await $.store.delete(denialsKey)

    const ran = await next(e)
    return r.findings.length > 0 && ran.deny === undefined
      ? { ...ran, context: [...(ran.context ?? []), `Pre-push review findings:\n${format(r)}`] }
      : ran
  }).catch(($, e, next) => {
    $.ui.status(undefined)
    $.ui.toast('pre-push review: failed, pushing without a review')
    return next(e)
  })
}

